　　    =${EXABOLT_Nrkc0} × ${GetEQFormat(0)}\\f(${EXABOLT_Acn},${EXABOLT_Acn0})${GetEQFormat(1)} × ${EXABOLT_ψsn} × ${EXABOLT_ψren} × ${EXABOLT_ψecn} 
　　    =${EXABOLT_Nrkc}N 
    ${GetEQSSubFormat('N','','Rdc')}=${EXABOLT_HASEARTHQUAKE:+k×} ${GetEQFormat(0)}\\f(${GetSSubFormat('N','','Rkc')},${GetSSubFormat('γ','','RcN')})${GetEQFormat(1)}
　　    =${EXABOLT_HASEARTHQUAKE:+${EXABOLT_nk}×} ${GetEQFormat(0)}\\f(${EXABOLT_Nrkc},${EXABOLT_γrcn})${GetEQFormat(1)}
