     ${GetEQSSubFormat('R','','tl')} = ${GetEQSSubFormat('R','','l')} + ${GetEQFormat(0)}\\f(1,${GetSSubFormat('h','','c,in')})${GetEQFormat(1)} + ${GetEQFormat(0)}\\f(1,${GetSSubFormat('h','','c,out')})${GetEQFormat(1)}
