替代板块总热阻  ${THERMEX_CONCRADITION:+(考虑替代面板的热辐射)}${THERMEX_CONCRADITION:*
     ${GetEQSSubFormat('R','','tr')} = ${GetEQSSubFormat('R','','r')} + ${GetEQFormat(0)}\\f(1,${GetSSubFormat('h','','c,in')})${GetEQFormat(1)} + ${GetEQFormat(0)}\\f(1,${GetSSubFormat('h','','c,out')})${GetEQFormat(1)}
        = ${THERMEX_BOARDRRRIGHT} + ${GetEQFormat(0)}\\f(1,${THERMEX_HIN})${GetEQFormat(1)} + ${GetEQFormat(0)}\\f(1,${THERMEX_HOUT})${GetEQFormat(1)}
        = ${THERMEX_BOARDRRTRIGHT}m^2.K/W } ${THERMEX_CONCRADITION:+
 同上计算有
     ${GetEQSSubFormat('R','','tr')} = ${GetEQSSubFormat('R','','r')} + ${GetEQFormat(0)}\\f(1,${GetSSubFormat('h','','in')})${GetEQFormat(1)} + ${GetEQFormat(0)}\\f(1,${GetSSubFormat('h','','out')})${GetEQFormat(1)}
        = ${THERMEX_BOARDRRRIGHT} + ${GetEQFormat(0)}\\f(1,${THERMEX_HIN})${GetEQFormat(1)} + ${GetEQFormat(0)}\\f(1,${THERMEX_HOUT})${GetEQFormat(1)}
        = ${THERMEX_BOARDRRTRIGHT}m^2.K/W } 
所以右上替代面板的U值
     ${GetEQSSubFormat('U','','pr')} = ${GetEQFormat(0)}\\f(1,${GetSSubFormat('R','','tr')})${GetEQFormat(1)}
        = ${THERMEX_BOARDRURIGHT}W/(m^2·K)
3) 计算框的U值
     ${GetEQSSubFormat('U','','f')} = ${GetEQFormat(0)}\\f(${GetSSubFormat('L','2D','f')} - ${GetSSubFormat('U','','pl')} × ${GetSSubFormat('b','','pl')} - ${GetSSubFormat('U','','pr')} × ${GetSSubFormat('b','','pr')},${GetSSubFormat('b','','f')})${GetEQFormat(1)}                       (JGJ/T151-2008  7.1.2-2)
其中
     ${GetEQSSubFormat('L','2D','f')} = ${GetEQFormat(0)}\\f(${GetSSubFormat('q','','w')} × (${GetSSubFormat('b','','f')} + ${GetSSubFormat('b','','pl')} + ${GetSSubFormat('b','','pr')}),${GetSSubFormat('T','','n,in')} - ${GetSSubFormat('T','','n,out')})${GetEQFormat(1)}         (JGJ/T151-2008  7.1.2-3)
           = ${GetEQFormat(0)}\\f(${THERMEX_HEATFLOWALL},${THERMEX_DISPREALTEMP})${GetEQFormat(1)}
           = ${THERMEX_HEATREPL}W/(m·K)
     ${GetEQSSubFormat('U','','f')} = ${GetEQFormat(0)}\\f(${THERMEX_HEATREPL} - ${THERMEX_BOARDRULEFT}×${THERMEX_BpLeft} - ${THERMEX_BOARDRURIGHT}×${THERMEX_BpRight},${THERMEX_Bf})${GetEQFormat(1)}
        = ${THERMEX_UF}W/(m^2·K)  }${THERMEX_REPLACE:*
所以该节点模型整体K值为\: ${GetEQFormat(0)}\\f(${THERMEX_HEATFLOWALL},${THERMEX_LENGTHALL}×${THERMEX_DISPREALTEMP})${GetEQFormat(1)} =${THERMEX_STRUCTKVALUE}W/(m^2·K) }

