${GetEQSSubFormat('S','','pe1')} = ${GetEQSSubFormat('G','','Ak')}×${GetEQSSubFormat('γ','','G')}×cos(θ) + ${GetEQSSubFormat('W','','kp')}×${GetEQSSubFormat('γ','','w')} + ${GetEQSSubFormat('ψ','','E')}×${GetEQSSubFormat('γ','','E')}×${GetEQSSubFormat('q','','EA')}×sin(θ)
     = ${LEANGLS_GAK}×${LEANGLS_GRatioP}×cos(${LEANGLS_Angle}) + ${LEANGLS_WKP}×${γwf} + ${ψE}×${γEf}×${LEANGLS_HEQK}×sin(${LEANGLS_Angle})
     = ${LEANGLS_COMPPEA}
${GetEQSSubFormat('S','','pe2')} = ${GetEQSSubFormat('G','','Ak')}×${GetEQSSubFormat('γ','','G')}×cos(θ) + ${GetEQSSubFormat('W','','kp')}×${GetEQSSubFormat('γ','','w')} - ${GetEQSSubFormat('ψ','','E')}×${GetEQSSubFormat('γ','','E')}×${GetEQSSubFormat('q','','EA')}×sin(θ)
