 ${GetEQSSubFormat('h','','s')} = 0.5×(${GetEQSSubFormat('h','','1')}+${GetEQSSubFormat('h','','2')})+${GetEQSSubFormat('h','','v')} = 0.5×(${SGPGLS_H1}+${SGPGLS_H2})+${SGPGLS_Hv}=${SGPGLS_Hs}
 ${GetEQSSubFormat('h','','s,1')}=${GetEQFormat(0)}\\f(${GetSSubFormat('h','','s')}×${GetSSubFormat('h','','1')},${GetSSubFormat('h','','1')}+${GetSSubFormat('h','','2')})${GetEQFormat(1)} = ${GetEQFormat(0)}\\f(${SGPGLS_Hs}×${SGPGLS_H1},${SGPGLS_H1}+${SGPGLS_H2})${GetEQFormat(1)} = ${SGPGLS_Hs1}
 ${GetEQSSubFormat('h','','s,2')}=${GetEQFormat(0)}\\f(${GetSSubFormat('h','','s')}×${GetSSubFormat('h','','2')},${GetSSubFormat('h','','1')}+${GetSSubFormat('h','','2')})${GetEQFormat(1)} = ${SGPGLS_Hs2}
 ${GetEQSSubFormat('I','','s')}  = ${GetEQSSubFormat('h','','1')}×${GetEQSSubFormat('h','2','s,2')} + ${GetEQSSubFormat('h','','2')}×${GetEQSSubFormat('h','2','s,1')}
