    = ${GetEQFormat(0)}\\f(1,1+9.6×\\f(${GetE(GLOB_BOARDMATERIAL)}×${SGPGLS_Is}×${SGPGLS_Hv},${SGPGLS_G}×${SGPGLS_Hs}^2×${SGPGLS_PS_blmm}^2))${GetEQFormat(1)}
