       = ${GetEQFormat(0)}\\r(\\f(${SGPGLS_PS_Efdisp}^3,${SGPGLS_H1} + 2×${SGPGLS_PS_Tt}×${SGPGLS_Hs2}))${GetEQFormat(1)}
       = ${SGPGLS_PS_Efstress1}mm
 ${GetEQSSubFormat('h','','2,ef.σ')} = ${GetEQFormat(0)}\\r(\\f(${GetSSubFormat('h','3','ef,w')},${GetSSubFormat('h','','2')} + 2× Г ×${GetSSubFormat('h','','s,1')}))${GetEQFormat(1)}
       = ${GetEQFormat(0)}\\r(\\f(${SGPGLS_PS_Efdisp}^3,${SGPGLS_H2} + 2×${SGPGLS_PS_Tt}×${SGPGLS_Hs1}))${GetEQFormat(1)}
       = ${SGPGLS_PS_Efstress2}mm  
  参数θ计算:
 ${GetEQSSubFormat('θ','','o')} = ${GetEQFormat(0)}\\f(${GetSSubFormat('q','','k')}×b^4×10^9,E×${GetSSubFormat('h','4','1,ef.σ')})${GetEQFormat(1)}      (JGJ102-2003  8.1.5-4)
  =${GetEQFormat(0)}\\f(${SGPGLS_COMPK}×${SGPGLS_PS_bl}^4×10^9,${GetE(GLOB_BOARDMATERIAL)}×${SGPGLS_PS_Efstress1}^4)${GetEQFormat(1)} 
