    =${GetEQFormat(0)}\\f(6×${SGPGLS_PS_Mr}×${SGPGLS_COMP}×${SGPGLS_PS_bl}^2×1000,${SGPGLS_PS_Efstress1}^2)${GetEQFormat(1)}×${SGPGLS_PS_Ngo}
    =${SGPGLS_PS_σwo}N/mm^2   
 ${GetEQSSubFormat('σ','','wi')}=${GetEQFormat(0)}\\f(6×m×q×b^2×1000,${GetSSubFormat('h','2','2,ef.σ')})${GetEQFormat(1)}×${GetEQSSubFormat('η','','i')}   
    =${SGPGLS_PS_σwi}N/mm^2
 ${SGPGLS_PS_STRESSO}N/mm^2${GetLess(IsNLarge(SGPGLS_PS_STRESSO,SGPGLS_PS_fgwo))}${GetEQSSubFormat('f','','g')}=${SGPGLS_PS_fgwo}N/mm^2 
 ${SGPGLS_PS_STRESSI}N/mm^2${GetLess(IsNLarge(SGPGLS_PS_STRESSI,SGPGLS_PS_fgwi))}${GetEQSSubFormat('f','','g')}=${SGPGLS_PS_fgwi}N/mm^2
